styleTag:
html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent;
}

#effectsHub {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  pointer-events: none;
}

#effectStage {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 100%;
  height: 100%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

#effectImage,
#effectVideo {
  position: absolute;
  left: 50%;
  top: 50%;
  display: none;
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  object-fit: contain;
  opacity: 0;
  transform:
    translate(-50%, -50%) scale(var(--meme-scale, 1));
  transform-origin: center center;
  pointer-events: none;
}

#effectImage.screen-effect,
#effectVideo.screen-effect {
  left: 50%;
  top: 50%;
  width: 100%;
  height: 100%;
  max-width: none;
  max-height: none;
  object-fit: fill;
  transform: translate(-50%, -50%) scale(1);
}

#effectImage.active,
#effectVideo.active {
  display: block;
}

/* Non-meme visuals fade in and out subtly. */
#effectImage.fade-effect.active,
#effectVideo.fade-effect.active {
  opacity: 1;
  animation: visualFadeIn .28s ease-out both;
}

#effectImage.fade-effect.fading-out,
#effectVideo.fade-effect.fading-out {
  animation: visualFadeOut .30s ease-in both;
}

/*
 * Memes use the same bounce timing and easing as the redemption tag.
 * The tag's own animation is unchanged.
 */
#effectImage.meme-effect.active,
#effectVideo.meme-effect.active {
  opacity: 1;
  animation: memeBounceIn .62s cubic-bezier(.18, .9, .25, 1.3) both;
}


#redemptionBanner {
  position: absolute;
  z-index: 100;
  left: 50%;
  top: 82%;
  display: none;
  max-width: min(760px, 88vw);
  box-sizing: border-box;
  padding: 12px 22px 14px;
  border-radius: var(--redeem-radius, 18px);
  color: var(--redeem-text-color, #ffffff);
  background: var(--redeem-background, rgba(10, 10, 18, .82));
  border: 2px solid var(--redeem-border-color, rgba(255, 255, 255, .26));
  box-shadow:
    0 12px 35px rgba(0, 0, 0, .5),
    0 0 24px var(--redeem-glow-color, rgba(255, 45, 149, .32));
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  text-align: center;
  transform: translate(-50%, -50%);
  transform-origin: center;
  pointer-events: none;
}

#redemptionBanner.active {
  display: block;
  animation:
    redemptionBounceIn .62s cubic-bezier(.18, .9, .25, 1.3) both,
    redemptionFloatOut .45s ease-in var(--redeem-exit-delay, 3.55s) forwards;
}

#redemptionBanner.meme-position {
  top: auto;
  bottom: auto;
}

#redemptionBanner.bottom-center {
  left: 50%;
  top: auto;
  bottom: var(--redeem-bottom-offset, 58px);
  transform: translateX(-50%);
}

#redemptionUser {
  font: 900 var(--redeem-user-size, 22px)/1.05 Arial, Helvetica, sans-serif;
  letter-spacing: .5px;
  overflow-wrap: anywhere;
  text-shadow: 0 2px 5px rgba(0, 0, 0, .9);
}

#redemptionReward {
  margin-top: 5px;
  font: 1000 var(--redeem-reward-size, 34px)/1 Arial, Helvetica, sans-serif;
  letter-spacing: .4px;
  overflow-wrap: anywhere;
  text-shadow:
    0 3px 0 rgba(0, 0, 0, .48),
    0 0 12px var(--redeem-glow-color, rgba(255, 45, 149, .42));
}

@keyframes redemptionBounceIn {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(.64) translateY(18px);
  }

  55% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1.13) translateY(-5px);
  }

  76% {
    transform: translate(-50%, -50%) scale(.96) translateY(2px);
  }

  100% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1) translateY(0);
  }
}

#redemptionBanner.bottom-center.active {
  animation:
    redemptionBottomBounceIn .62s cubic-bezier(.18, .9, .25, 1.3) both,
    redemptionBottomFloatOut .45s ease-in var(--redeem-exit-delay, 3.55s) forwards;
}

@keyframes redemptionBottomBounceIn {
  0% {
    opacity: 0;
    transform: translateX(-50%) scale(.64) translateY(18px);
  }

  55% {
    opacity: 1;
    transform: translateX(-50%) scale(1.13) translateY(-5px);
  }

  76% {
    transform: translateX(-50%) scale(.96) translateY(2px);
  }

  100% {
    opacity: 1;
    transform: translateX(-50%) scale(1) translateY(0);
  }
}

@keyframes redemptionFloatOut {
  to {
    opacity: 0;
    transform: translate(-50%, -50%) scale(.94) translateY(-15px);
  }
}

@keyframes redemptionBottomFloatOut {
  to {
    opacity: 0;
    transform: translateX(-50%) scale(.94) translateY(-15px);
  }
}

#debugPanel {
  position: absolute;
  left: 14px;
  bottom: 14px;
  z-index: 999;
  display: none;
  min-width: 285px;
  padding: 10px 12px;
  border: 1px solid rgba(255, 255, 255, .22);
  border-radius: 10px;
  color: #ffffff;
  background: rgba(0, 0, 0, .78);
  font: 700 12px/1.45 Arial, sans-serif;
  letter-spacing: .5px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, .4);
}

#debugPanel.visible {
  display: block;
}

@keyframes visualFadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes visualFadeOut {
  from {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

@keyframes memeBounceIn {
  0% {
    opacity: 0;
    transform:
      translate(-50%, -50%) scale(calc(var(--meme-scale, 1) * .64)) translateY(18px);
  }

  55% {
    opacity: 1;
    transform:
      translate(-50%, -50%) scale(calc(var(--meme-scale, 1) * 1.13)) translateY(-5px);
  }

  76% {
    transform:
      translate(-50%, -50%) scale(calc(var(--effect-scale, 1) * .96)) translateY(2px);
  }

  100% {
    opacity: 1;
    transform:
      translate(-50%, -50%) scale(var(--effect-scale, 1)) translateY(0);
  }
}

