const effectStage = document.getElementById("effectStage");
const effectImage = document.getElementById("effectImage");
const effectVideo = document.getElementById("effectVideo");
const redemptionBanner = document.getElementById("redemptionBanner");
const redemptionUser = document.getElementById("redemptionUser");
const redemptionReward = document.getElementById("redemptionReward");

const debugPanel = document.getElementById("debugPanel");
const connectionStatus = document.getElementById("connectionStatus");
const manifestStatus = document.getElementById("manifestStatus");
const effectStatus = document.getElementById("effectStatus");

const DEFAULT_MANIFEST_URL =
  "https://raw.githubusercontent.com/MaruFPS/MarusWidgets/main/widgets/Channel-Points-Hub/channel-point-effects/effects.json";

let manifestUrl =
  String("{manifest_url}" || "").trim() ||
  DEFAULT_MANIFEST_URL;

let useRemoteConnection =
  parseToggle("{use_remote_connection}");

let localWebSocketUrl =
  String("{local_websocket_url}" || "").trim() ||
  "ws://127.0.0.1:8080/";

let remoteWebSocketUrl =
  String("{remote_websocket_url}" || "").trim();

let streamerBotPassword =
  String("{streamerbot_password}" || "");

let effectScale = readNumber("{effect_scale}", 1);
let effectPositionX = readNumber("{effect_position_x}", 50);
let effectPositionY = readNumber("{effect_position_y}", 50);

let memeScale = readNumber("{meme_scale}", 1);
let memePositionX = readNumber("{meme_position_x}", 50);
let memePositionY = readNumber("{meme_position_y}", 50);

let durationOverrideMs = readNumber("{duration_override_ms}", 0);
let showDebug = parseToggle("{show_debug_panel}");
let queueEnabled = parseToggle("{queue_effects}");
let effectsEnabled = parseToggle("{effects_enabled}");
let disabledActionName = String("{disabled_action_name}" || "").trim();
let disabledMessageCooldownSeconds = readNumber("{disabled_message_cooldown_seconds}", 15);
let lastDisabledMessageAt = 0;
let showRedemptionText = parseToggle("{show_redemption_text}");
let redemptionTextGapPx = readNumber("{redemption_text_gap_px}", 22);
let redemptionBottomOffsetPx = readNumber("{redemption_bottom_offset_px}", 58);

let manifest = null;
let effectMap = new Map();

let socket = null;
let reconnectTimer = 0;
let socketAuthenticated = false;
let socketSubscribed = false;

let activeEffectId = "";
let activeCleanupTimer = 0;
let activeFadeTimer = 0;
let activeVideoMonitor = 0;
let activeAudio = null;
let effectQueue = [];
let isPlaying = false;
let playbackGeneration = 0;

function debug(...args) {
  console.log("[POGLY EFFECTS HUB]", ...args);
}

function activeConnectionLabel() {
  return useRemoteConnection
    ? "REMOTE"
    : "LOCAL";
}

function resolvedStreamerBotSocketUrl() {
  return useRemoteConnection
    ? remoteWebSocketUrl
    : localWebSocketUrl;
}

function parseToggle(value) {
  if (value === true) return true;

  const normalized = String(value ?? "")
    .trim()
    .toLowerCase();

  return ![
    "",
    "false",
    "0",
    "off",
    "no",
    "disabled"
  ].includes(normalized);
}

function readNumber(value, fallback) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function joinUrl(base, path) {
  const cleanBase = String(base || "").replace(/\/+$/, "");
  const cleanPath = String(path || "").replace(/^\/+/, "");
  return `${cleanBase}/${cleanPath}`;
}

function applyLiveLayout() {
  document.documentElement.style.setProperty(
    "--effect-scale",
    String(Math.max(.05, effectScale))
  );

  document.documentElement.style.setProperty(
    "--meme-scale",
    String(Math.max(.05, memeScale))
  );

  effectImage.style.left = `${effectPositionX}%`;
  effectImage.style.top = `${effectPositionY}%`;

  effectVideo.style.left = `${effectPositionX}%`;
  effectVideo.style.top = `${effectPositionY}%`;

  document.documentElement.style.setProperty(
    "--redeem-text-color",
    String("{redemption_text_color}" || "#ffffff")
  );
  document.documentElement.style.setProperty(
    "--redeem-background",
    String("{redemption_background}" || "rgba(10,10,18,.82)")
  );
  document.documentElement.style.setProperty(
    "--redeem-border-color",
    String("{redemption_border_color}" || "rgba(255,255,255,.26)")
  );
  document.documentElement.style.setProperty(
    "--redeem-glow-color",
    String("{redemption_glow_color}" || "rgba(255,45,149,.42)")
  );
  document.documentElement.style.setProperty(
    "--redeem-bottom-offset",
    `${Math.max(0, redemptionBottomOffsetPx)}px`
  );

  debugPanel.classList.toggle("visible", showDebug);
}

function setConnectionStatus(text) {
  connectionStatus.textContent = text;
}

function setManifestStatus(text) {
  manifestStatus.textContent = text;
}

function setEffectStatus(text) {
  effectStatus.textContent = text;
}

function runStreamerBotAction(actionName, args = {}) {
  const cleanName = String(actionName || "").trim();

  if (
    !cleanName ||
    !socket ||
    socket.readyState !== WebSocket.OPEN ||
    !socketAuthenticated
  ) {
    return false;
  }

  try {
    socket.send(JSON.stringify({
      request: "DoAction",
      id: `pogly-effects-action-${Date.now()}`,
      action: { name: cleanName },
      args
    }));

    return true;
  } catch (error) {
    debug("Could not execute Streamer.bot action", cleanName, error);
    return false;
  }
}

function notifyEffectsDisabled(effectId, redemptionData = {}) {
  const cooldownMs = Math.max(0, disabledMessageCooldownSeconds) * 1000;
  const now = Date.now();

  if (cooldownMs > 0 && now - lastDisabledMessageAt < cooldownMs) {
    return;
  }

  const details = redemptionDetailsFromData(redemptionData, null);
  const sent = runStreamerBotAction(disabledActionName, {
    effectId: String(effectId || ""),
    effectUserName: details.userName,
    effectRewardName: details.rewardName,
    effectsEnabled: false
  });

  if (sent) {
    lastDisabledMessageAt = now;
  }
}

function setEffectsEnabled(enabled) {
  effectsEnabled = Boolean(enabled);

  if (!effectsEnabled) {
    effectQueue = [];
    setEffectStatus(
      isPlaying
        ? "EFFECTS: DISABLED — CURRENT EFFECT FINISHING"
        : "EFFECTS: DISABLED"
    );
  } else if (!isPlaying) {
    setEffectStatus("EFFECT: IDLE");
  }

  debug("Effects enabled changed", effectsEnabled);
}

async function loadManifest() {
  setManifestStatus("MANIFEST: LOADING");

  try {
    const cacheBuster =
      `${manifestUrl.includes("?") ? "&" : "?"}t=${Date.now()}`;

    const response = await fetch(manifestUrl + cacheBuster, {
      cache: "no-store"
    });

    if (!response.ok) {
      throw new Error(`HTTP ${response.status}`);
    }

    const data = await response.json();

    if (!data || !Array.isArray(data.effects)) {
      throw new Error("effects array missing");
    }

    manifest = data;
    effectMap = new Map();

    data.effects.forEach(effect => {
      const id = String(effect?.id || "").trim();

      if (id) {
        effectMap.set(id, effect);
      }
    });

    setManifestStatus(
      `MANIFEST: ${effectMap.size} EFFECTS READY`
    );

    debug("Manifest loaded", data);
    return true;
  } catch (error) {
    manifest = null;
    effectMap.clear();

    setManifestStatus("MANIFEST: LOAD FAILED");
    debug("Manifest load failed", error);
    return false;
  }
}

function clearCleanupTimer() {
  if (activeCleanupTimer) {
    clearTimeout(activeCleanupTimer);
    activeCleanupTimer = 0;
  }
}

function clearFadeTimer() {
  if (activeFadeTimer) {
    clearTimeout(activeFadeTimer);
    activeFadeTimer = 0;
  }
}

function clearVideoMonitor() {
  if (activeVideoMonitor) {
    cancelAnimationFrame(activeVideoMonitor);
    activeVideoMonitor = 0;
  }
}

function stopActiveAudio() {
  if (!activeAudio) return;

  try {
    activeAudio.pause();
    activeAudio.currentTime = 0;
  } catch (_) { }

  activeAudio = null;
}

function resetImageElement() {
  effectImage.onload = null;
  effectImage.onerror = null;

  effectImage.classList.remove(
    "active",
    "screen-effect",
    "fade-effect",
    "meme-effect",
    "fading-out"
  );
  effectImage.style.display = "none";
  effectImage.style.opacity = "0";
  effectImage.style.width = "auto";
  effectImage.style.height = "auto";
  effectImage.style.maxWidth = "100%";
  effectImage.style.maxHeight = "100%";
  effectImage.style.objectFit = "contain";
  effectImage.style.transform =
    "translate(-50%, -50%) scale(var(--effect-scale, 1))";

  effectImage.removeAttribute("src");
}

function resetVideoElement() {
  effectVideo.onloadedmetadata = null;
  effectVideo.oncanplay = null;
  effectVideo.onplaying = null;
  effectVideo.onerror = null;
  effectVideo.onended = null;

  effectVideo.classList.remove(
    "active",
    "screen-effect",
    "fade-effect",
    "meme-effect",
    "fading-out"
  );
  effectVideo.style.display = "none";
  effectVideo.style.opacity = "0";
  effectVideo.style.width = "auto";
  effectVideo.style.height = "auto";
  effectVideo.style.maxWidth = "100%";
  effectVideo.style.maxHeight = "100%";
  effectVideo.style.objectFit = "contain";
  effectVideo.style.transform =
    "translate(-50%, -50%) scale(var(--effect-scale, 1))";

  try {
    effectVideo.pause();
    effectVideo.currentTime = 0;
  } catch (_) { }

  effectVideo.removeAttribute("src");

  try {
    effectVideo.load();
  } catch (_) { }
}

function resetMedia({ invalidatePlayback = true } = {}) {
  if (invalidatePlayback) {
    playbackGeneration += 1;
  }

  clearCleanupTimer();
  clearFadeTimer();
  clearVideoMonitor();
  stopActiveAudio();

  resetImageElement();
  resetVideoElement();

  hideRedemptionBanner();
  activeEffectId = "";
}

function finishCurrentEffect(expectedGeneration = playbackGeneration) {
  if (expectedGeneration !== playbackGeneration) {
    debug("Ignored stale cleanup callback", {
      expectedGeneration,
      playbackGeneration
    });
    return;
  }

  resetMedia();
  isPlaying = false;
  setEffectStatus("EFFECT: IDLE");

  if (effectQueue.length) {
    const nextEffect = effectQueue.shift();
    playEffect(nextEffect.effectId, nextEffect.redemptionData);
  }
}

function normalizedDuration(effect) {
  if (durationOverrideMs > 0) {
    return Math.max(100, durationOverrideMs);
  }

  const duration = Number(effect?.durationMs);
  return Number.isFinite(duration) && duration > 0
    ? duration
    : 5000;
}

function normalizedEndOffset(effect) {
  const offset = Number(
    effect?.endOffsetMs ??
    effect?.hideEarlyMs ??
    0
  );

  return Number.isFinite(offset)
    ? Math.max(0, offset)
    : 0;
}

function effectivePlaybackDuration(effect, duration) {
  const endOffsetMs = normalizedEndOffset(effect);

  return Math.max(
    100,
    duration - endOffsetMs
  );
}

function resolveAssetUrl(path) {
  if (!path) return "";

  const value = String(path).trim();

  if (/^https?:\/\//i.test(value)) {
    return value;
  }

  return joinUrl(manifest?.baseUrl || "", value);
}

function normalizedCategory(effect) {
  return String(effect?.category || "")
    .trim()
    .toLowerCase()
    .replace(/[_\s]+/g, "-");
}

function isScreenEffect(effect) {
  const category = normalizedCategory(effect);

  return [
    "screen-effect",
    "screen-effects",
    "fullscreen",
    "full-screen"
  ].includes(category);
}

function isMemeEffect(effect) {
  const category = normalizedCategory(effect);

  return [
    "meme",
    "memes"
  ].includes(category);
}

function effectScaleFor(effect) {
  return isMemeEffect(effect)
    ? Math.max(.05, memeScale)
    : Math.max(.05, effectScale);
}

function effectPositionFor(effect) {
  return isMemeEffect(effect)
    ? {
      x: memePositionX,
      y: memePositionY
    }
    : {
      x: effectPositionX,
      y: effectPositionY
    };
}

function applyEffectAnimationClass(effect, mediaElement) {
  const meme = isMemeEffect(effect);

  mediaElement.classList.remove(
    "fade-effect",
    "meme-effect",
    "fading-out"
  );

  mediaElement.classList.add(
    meme ? "meme-effect" : "fade-effect"
  );
}

function scheduleVisualFadeOut(
  effect,
  mediaElement,
  visibleDuration,
  generation
) {
  clearFadeTimer();

  if (isMemeEffect(effect)) return;

  const fadeDurationMs = 300;
  const fadeStartMs = Math.max(
    0,
    visibleDuration - fadeDurationMs
  );

  activeFadeTimer = setTimeout(() => {
    if (generation !== playbackGeneration) return;
    mediaElement.classList.add("fading-out");
  }, fadeStartMs);
}

function applyEffectLayout(effect, mediaElement) {
  const fullscreen = isScreenEffect(effect);
  const otherElement =
    mediaElement === effectImage
      ? effectVideo
      : effectImage;

  otherElement.classList.remove(
    "active",
    "screen-effect",
    "fade-effect",
    "meme-effect",
    "fading-out"
  );
  otherElement.style.display = "none";

  mediaElement.classList.toggle("screen-effect", fullscreen);

  if (fullscreen) {
    mediaElement.style.left = "50%";
    mediaElement.style.top = "50%";
    mediaElement.style.width = "100%";
    mediaElement.style.height = "100%";
    mediaElement.style.maxWidth = "none";
    mediaElement.style.maxHeight = "none";
    mediaElement.style.objectFit = "fill";
    mediaElement.style.transform =
      "translate(-50%, -50%) scale(1)";
  } else {
    const position = effectPositionFor(effect);
    const scaleVariable = isMemeEffect(effect)
      ? "var(--meme-scale, 1)"
      : "var(--effect-scale, 1)";

    mediaElement.style.left = `${position.x}%`;
    mediaElement.style.top = `${position.y}%`;
    mediaElement.style.width = "auto";
    mediaElement.style.height = "auto";
    mediaElement.style.maxWidth = "100%";
    mediaElement.style.maxHeight = "100%";
    mediaElement.style.objectFit = "contain";
    mediaElement.style.transform =
      `translate(-50%, -50%) scale(${scaleVariable})`;
  }
}


function cleanDisplayValue(value, fallback = "") {
  const text = String(value ?? "").trim();
  return text || fallback;
}

function redemptionDetailsFromData(data, effect) {
  const source = data && typeof data === "object" ? data : {};

  const userName = cleanDisplayValue(
    source.effectUserName ||
    source.userName ||
    source.user ||
    source.userLogin ||
    source.displayName,
    "Someone"
  );

  const rewardName = cleanDisplayValue(
    source.effectRewardName ||
    source.rewardName ||
    source.reward ||
    effect?.label,
    effect?.label || "Effect"
  );

  return { userName, rewardName };
}

function hideRedemptionBanner() {
  redemptionBanner.classList.remove(
    "active",
    "meme-position",
    "bottom-center"
  );
}

function showRedemptionBanner(
  effect,
  redemptionData = {},
  effectDurationMs = 5000
) {
  hideRedemptionBanner();

  if (!showRedemptionText) return;

  const details = redemptionDetailsFromData(redemptionData, effect);
  redemptionUser.textContent = `${details.userName} redeemed`;
  redemptionReward.textContent = details.rewardName;

  const category = normalizedCategory(effect);
  const bottomPlacement =
    category === "sounds" ||
    category === "sound" ||
    isScreenEffect(effect) ||
    !effect?.visual?.file;

  if (bottomPlacement) {
    redemptionBanner.classList.add("bottom-center");
    redemptionBanner.style.left = "50%";
    redemptionBanner.style.top = "";
    redemptionBanner.style.bottom = `${Math.max(0, redemptionBottomOffsetPx)}px`;
  } else {
    redemptionBanner.classList.add("meme-position");
    redemptionBanner.style.left = `${memePositionX}%`;

    const stageHeight = Math.max(
      1,
      effectStage.clientHeight ||
      document.documentElement.clientHeight ||
      1080
    );

    const memeTopPx = stageHeight * (memePositionY / 100);
    const estimatedHalfHeight = 180 * Math.max(.1, memeScale);
    const bannerTopPx = Math.max(
      45,
      memeTopPx - estimatedHalfHeight - redemptionTextGapPx
    );

    redemptionBanner.style.top = `${bannerTopPx}px`;
    redemptionBanner.style.bottom = "";
  }

  /*
   * The display tag always follows the active effect's duration.
   * There is no separate tag timer to drift out of sync.
   */
  const safeDuration = Math.max(800, effectDurationMs);
  document.documentElement.style.setProperty(
    "--redeem-exit-delay",
    `${Math.max(.15, (safeDuration - 450) / 1000)}s`
  );

  void redemptionBanner.offsetWidth;
  redemptionBanner.classList.add("active");
}

function playSound(effect) {
  const soundFile = effect?.sound?.file;
  if (!soundFile) return;

  const url = resolveAssetUrl(soundFile);
  if (!url) return;

  activeAudio = new Audio(url);

  let volume = Number(effect?.sound?.volume);
  if (!Number.isFinite(volume)) volume = 1;
  if (volume > 1) volume /= 100;

  activeAudio.volume = Math.max(0, Math.min(1, volume));
  activeAudio.play().catch(error => {
    debug("Sound playback blocked or failed", error);
  });
}

function showImage(effect, url, duration, generation) {
  resetImageElement();
  applyEffectLayout(effect, effectImage);
  applyEffectAnimationClass(effect, effectImage);

  const separator = url.includes("?") ? "&" : "?";
  const playbackUrl = `${url}${separator}play=${Date.now()}`;

  effectImage.onload = () => {
    if (generation !== playbackGeneration) return;

    effectImage.style.display = "block";
    effectImage.classList.add("active");

    scheduleVisualFadeOut(
      effect,
      effectImage,
      duration,
      generation
    );
  };

  effectImage.onerror = () => {
    if (generation !== playbackGeneration) return;

    debug("Image failed to load", url);
    finishCurrentEffect(generation);
  };

  effectImage.src = playbackUrl;

  activeCleanupTimer = setTimeout(
    () => finishCurrentEffect(generation),
    duration
  );
}

function showVideo(effect, url, duration, generation) {
  resetVideoElement();
  applyEffectLayout(effect, effectVideo);
  applyEffectAnimationClass(effect, effectVideo);
  clearCleanupTimer();
  clearVideoMonitor();

  const endOffsetMs = normalizedEndOffset(effect);
  let metadataDurationMs = 0;
  let cleanupScheduled = false;

  function scheduleVideoCleanup() {
    if (
      cleanupScheduled ||
      generation !== playbackGeneration
    ) {
      return;
    }

    cleanupScheduled = true;

    const usableDurationMs =
      metadataDurationMs > 0
        ? Math.min(duration, metadataDurationMs)
        : duration;

    const playbackDuration = Math.max(
      100,
      usableDurationMs - endOffsetMs
    );

    scheduleVisualFadeOut(
      effect,
      effectVideo,
      playbackDuration,
      generation
    );

    activeCleanupTimer = setTimeout(
      () => finishCurrentEffect(generation),
      playbackDuration
    );

    debug("Video cleanup scheduled", {
      manifestDuration: duration,
      metadataDuration: metadataDurationMs,
      usableDuration: usableDurationMs,
      endOffsetMs,
      playbackDuration,
      generation
    });
  }

  function monitorVideoEnd() {
    if (generation !== playbackGeneration) return;

    if (
      endOffsetMs > 0 &&
      Number.isFinite(effectVideo.duration) &&
      effectVideo.duration > 0
    ) {
      const remainingMs =
        (effectVideo.duration - effectVideo.currentTime) * 1000;

      if (remainingMs <= endOffsetMs) {
        finishCurrentEffect(generation);
        return;
      }
    }

    activeVideoMonitor = requestAnimationFrame(
      monitorVideoEnd
    );
  }

  effectVideo.loop = false;
  effectVideo.muted = Boolean(effect?.visual?.muted);

  let videoVolume = Number(effect?.visual?.volume);

  if (!Number.isFinite(videoVolume)) {
    videoVolume = 1;
  }

  if (videoVolume > 1) {
    videoVolume /= 100;
  }

  effectVideo.volume = Math.max(
    0,
    Math.min(1, videoVolume)
  );

  effectVideo.onloadedmetadata = () => {
    if (generation !== playbackGeneration) return;

    if (
      Number.isFinite(effectVideo.duration) &&
      effectVideo.duration > 0
    ) {
      metadataDurationMs = effectVideo.duration * 1000;
    }
  };

  effectVideo.oncanplay = () => {
    if (generation !== playbackGeneration) return;

    effectVideo.style.display = "block";
    effectVideo.classList.add("active");

    effectVideo.play().catch(error => {
      if (generation !== playbackGeneration) return;
      debug("Video playback failed", error);
      finishCurrentEffect(generation);
    });
  };

  effectVideo.onplaying = () => {
    if (generation !== playbackGeneration) return;

    scheduleVideoCleanup();

    if (endOffsetMs > 0 && !activeVideoMonitor) {
      activeVideoMonitor = requestAnimationFrame(
        monitorVideoEnd
      );
    }
  };

  effectVideo.onerror = () => {
    if (generation !== playbackGeneration) return;

    debug("Video failed to load", url);
    finishCurrentEffect(generation);
  };

  effectVideo.onended = () => {
    finishCurrentEffect(generation);
  };

  effectVideo.src = url;
  effectVideo.load();
}


async function playEffect(effectId, redemptionData = {}) {
  const cleanId = String(effectId || "").trim();
  if (!cleanId) return;

  if (!effectsEnabled) {
    setEffectStatus("EFFECTS: DISABLED");
    notifyEffectsDisabled(cleanId, redemptionData);
    debug("Ignored effect while effects are disabled", {
      effectId: cleanId,
      redemptionData
    });
    return;
  }

  if (!manifest || !effectMap.size) {
    const loaded = await loadManifest();
    if (!loaded) return;
  }

  const effect = effectMap.get(cleanId);

  if (!effect) {
    setEffectStatus(`EFFECT NOT FOUND: ${cleanId}`);
    debug("Unknown effect ID", cleanId);
    return;
  }

  if (effect.enabled === false) {
    setEffectStatus(`EFFECT DISABLED: ${cleanId}`);
    debug("Effect disabled", cleanId);
    return;
  }

  if (isPlaying) {
    if (queueEnabled) {
      effectQueue.push({
        effectId: cleanId,
        redemptionData
      });
      setEffectStatus(
        `QUEUED: ${cleanId} (${effectQueue.length})`
      );
    } else {
      resetMedia();
      isPlaying = false;
    }

    if (queueEnabled) return;
  }

  const visual = effect.visual || null;
  const sound = effect.sound || null;

  const visualFile = visual?.file || "";
  const soundFile = sound?.file || "";

  const hasVisual = Boolean(visualFile);
  const hasSound = Boolean(soundFile);

  if (!hasVisual && !hasSound) {
    setEffectStatus(`NO MEDIA: ${cleanId}`);
    debug("Effect has neither visual nor sound", effect);
    return;
  }

  const duration = normalizedDuration(effect);

  /*
   * Start every effect from a completely clean media state.
   * The generation token prevents callbacks from an older effect
   * from hiding or restyling the current one.
   */
  resetMedia();
  const generation = playbackGeneration;

  activeEffectId = cleanId;
  isPlaying = true;

  showRedemptionBanner(
    effect,
    redemptionData,
    duration
  );

  setEffectStatus(
    `PLAYING: ${effect.label || cleanId}`
  );

  if (hasSound) {
    playSound(effect);
  }

  if (!hasVisual) {
    activeCleanupTimer = setTimeout(
      () => finishCurrentEffect(generation),
      duration
    );

    debug("Playing sound-only effect", {
      id: cleanId,
      soundUrl: resolveAssetUrl(soundFile),
      duration
    });

    return;
  }

  const visualType = String(visual?.type || "image")
    .trim()
    .toLowerCase();

  const visualUrl = resolveAssetUrl(visualFile);

  if (
    visualType === "video" ||
    /\.(webm|mp4|mov)(\?|$)/i.test(visualUrl)
  ) {
    showVideo(effect, visualUrl, duration, generation);
  } else {
    showImage(effect, visualUrl, duration, generation);
  }

  debug("Playing visual effect", {
    id: cleanId,
    category: normalizedCategory(effect),
    layout: isScreenEffect(effect) ? "full-screen" : "shared-meme-position",
    visualType,
    visualUrl,
    hasSound,
    duration,
    endOffsetMs: normalizedEndOffset(effect),
    playbackDuration: effectivePlaybackDuration(effect, duration)
  });
}

function extractCustomEventName(message) {
  if (
    message?.event?.source === "Custom" &&
    message?.event?.type === "Event"
  ) {
    return String(
      message?.data?.eventName ||
      message?.data?.name ||
      message?.data?.event ||
      ""
    ).trim();
  }

  return "";
}

function handleEffectCommand(payload) {
  if (!payload || typeof payload !== "object") return;

  const effectId =
    payload.effect ||
    payload.effectId ||
    payload.playEffect ||
    "";

  const command =
    payload.command ||
    payload.type ||
    "";

  if (
    effectId &&
    (
      !command ||
      command === "playEffect" ||
      command === "effect"
    )
  ) {
    playEffect(effectId, payload);
  }
}

function handleStreamerBotMessage(message) {
  const eventName = extractCustomEventName(message);

  if (eventName.startsWith("effects:play:")) {
    const effectId = eventName
      .slice("effects:play:".length)
      .trim();

    const eventData =
      message?.data?.data &&
        typeof message.data.data === "object"
        ? { ...message.data, ...message.data.data }
        : (message?.data || {});

    playEffect(effectId, eventData);
    return;
  }

  if (
    message?.event?.source === "General" &&
    message?.event?.type === "Custom"
  ) {
    let customData =
      message?.data?.data ??
      message?.data?.message ??
      message?.data;

    if (typeof customData === "string") {
      try {
        customData = JSON.parse(customData);
      } catch (error) {
        debug("Could not parse General.Custom payload", customData);
      }
    }

    handleEffectCommand(customData);
    return;
  }

  let directPayload = message;

  if (
    message?.data &&
    typeof message.data === "object" &&
    (
      message.data.effect ||
      message.data.effectId ||
      message.data.playEffect
    )
  ) {
    directPayload = message.data;
  }

  handleEffectCommand(directPayload);
}


function bytesToBase64(bytes) {
  let binary = "";

  for (let index = 0; index < bytes.length; index += 1) {
    binary += String.fromCharCode(bytes[index]);
  }

  return btoa(binary);
}

async function sha256Base64(value) {
  if (!globalThis.crypto?.subtle) {
    throw new Error("Web Crypto API is unavailable");
  }

  const encoded = new TextEncoder().encode(String(value));
  const digest = await globalThis.crypto.subtle.digest("SHA-256", encoded);

  return bytesToBase64(new Uint8Array(digest));
}

async function buildAuthentication(password, salt, challenge) {
  const secret = await sha256Base64(
    String(password) + String(salt)
  );

  return sha256Base64(
    secret + String(challenge)
  );
}

function subscribeToStreamerBot() {
  if (!socket || socket.readyState !== WebSocket.OPEN) return;
  if (socketSubscribed) return;

  socketSubscribed = true;

  socket.send(JSON.stringify({
    request: "Subscribe",
    id: "pogly-effects-subscribe",
    events: {
      Custom: ["Event"],
      General: ["Custom"]
    }
  }));

  socket.send(JSON.stringify({
    request: "GetInfo",
    id: "pogly-effects-info"
  }));
}

async function handleHelloMessage(message) {
  const authentication = message?.authentication;

  if (!authentication) {
    socketAuthenticated = true;
    subscribeToStreamerBot();
    return;
  }

  if (!streamerBotPassword) {
    socketAuthenticated = false;
    setConnectionStatus("STREAMER.BOT: PASSWORD REQUIRED");
    debug("Streamer.bot authentication is enabled, but no password was provided");
    return;
  }

  try {
    setConnectionStatus("STREAMER.BOT: AUTHENTICATING");

    const authenticationString = await buildAuthentication(
      streamerBotPassword,
      authentication.salt,
      authentication.challenge
    );

    socket.send(JSON.stringify({
      request: "Authenticate",
      id: "pogly-effects-authenticate",
      authentication: authenticationString
    }));
  } catch (error) {
    socketAuthenticated = false;
    setConnectionStatus("STREAMER.BOT: AUTH FAILED");
    debug("Could not create Streamer.bot authentication response", error);
  }
}

function scheduleReconnect() {
  if (reconnectTimer) return;

  reconnectTimer = setTimeout(() => {
    reconnectTimer = 0;
    connectToStreamerBot();
  }, 3000);
}

function connectToStreamerBot() {
  if (
    socket &&
    (
      socket.readyState === WebSocket.OPEN ||
      socket.readyState === WebSocket.CONNECTING
    )
  ) {
    return;
  }

  const activeSocketUrl = resolvedStreamerBotSocketUrl();
  const connectionLabel = activeConnectionLabel();

  if (!activeSocketUrl) {
    setConnectionStatus(
      `STREAMER.BOT: ${connectionLabel} URL REQUIRED`
    );
    debug(
      "No Streamer.bot WebSocket URL is configured",
      { useRemoteConnection }
    );
    return;
  }

  setConnectionStatus(
    `STREAMER.BOT: CONNECTING (${connectionLabel})`
  );

  try {
    socket = new WebSocket(activeSocketUrl);
  } catch (error) {
    setConnectionStatus(
      `STREAMER.BOT: OFFLINE (${connectionLabel})`
    );
    debug("WebSocket creation failed", error);
    scheduleReconnect();
    return;
  }

  socket.addEventListener("open", () => {
    socketAuthenticated = false;
    socketSubscribed = false;
    setConnectionStatus(
      `STREAMER.BOT: CONNECTED (${connectionLabel}) — WAITING FOR HELLO`
    );

    debug(
      "Connected to Streamer.bot",
      {
        connectionMode: activeConnectionLabel(),
        socketUrl: activeSocketUrl
      }
    );
  });

  socket.addEventListener("message", event => {
    let message;

    try {
      message = JSON.parse(event.data);
    } catch (error) {
      debug("Non-JSON WebSocket message", event.data);
      return;
    }

    if (message?.request === "Hello") {
      handleHelloMessage(message);
      return;
    }

    if (message?.id === "pogly-effects-authenticate") {
      if (message?.status === "ok") {
        socketAuthenticated = true;
        setConnectionStatus("STREAMER.BOT: AUTHENTICATED");
        subscribeToStreamerBot();
      } else {
        socketAuthenticated = false;
        socketSubscribed = false;
        setConnectionStatus("STREAMER.BOT: WRONG PASSWORD");
        debug("Streamer.bot authentication failed", message);
      }

      return;
    }

    if (
      message?.id === "pogly-effects-info" &&
      message?.status === "ok"
    ) {
      const version = message?.info?.version
        ? ` v${message.info.version}`
        : "";

      setConnectionStatus(
        `STREAMER.BOT${version}: CONNECTED (${activeConnectionLabel()})`
      );
    }

    handleStreamerBotMessage(message);
  });

  socket.addEventListener("close", () => {
    socketAuthenticated = false;
    socketSubscribed = false;
    setConnectionStatus(
      `STREAMER.BOT: OFFLINE (${activeConnectionLabel()})`
    );
    scheduleReconnect();
  });

  socket.addEventListener("error", error => {
    debug("WebSocket error", error);
  });
}

function reconnectStreamerBot() {
  if (reconnectTimer) {
    clearTimeout(reconnectTimer);
    reconnectTimer = 0;
  }

  if (socket) {
    try {
      socket.close();
    } catch (_) { }
  }

  socket = null;
  socketAuthenticated = false;
  socketSubscribed = false;
  connectToStreamerBot();
}

function onLiveVariableUpdate(name, value) {
  if (name === "manifest_url") {
    manifestUrl =
      String(value || "").trim() ||
      DEFAULT_MANIFEST_URL;

    loadManifest();
  }

  else if (name === "reload_manifest") {
    loadManifest();
  }

  else if (name === "use_remote_connection") {
    useRemoteConnection = parseToggle(value);
    reconnectStreamerBot();
  }

  else if (name === "local_websocket_url") {
    localWebSocketUrl =
      String(value || "").trim() ||
      "ws://127.0.0.1:8080/";

    reconnectStreamerBot();
  }

  else if (name === "remote_websocket_url") {
    remoteWebSocketUrl = String(value || "").trim();
    reconnectStreamerBot();
  }

  else if (name === "streamerbot_password") {
    streamerBotPassword = String(value || "");
    reconnectStreamerBot();
  }

  else if (name === "effect_scale") {
    effectScale = readNumber(value, 1);
    applyLiveLayout();
  }

  else if (name === "effect_position_x") {
    effectPositionX = readNumber(value, 50);
    applyLiveLayout();
  }

  else if (name === "effect_position_y") {
    effectPositionY = readNumber(value, 50);
    applyLiveLayout();
  }

  else if (name === "meme_scale") {
    memeScale = readNumber(value, 1);
    applyLiveLayout();
  }

  else if (name === "meme_position_x") {
    memePositionX = readNumber(value, 50);
    applyLiveLayout();
  }

  else if (name === "meme_position_y") {
    memePositionY = readNumber(value, 50);
    applyLiveLayout();
  }

  else if (name === "duration_override_ms") {
    durationOverrideMs = readNumber(value, 0);
  }

  else if (name === "queue_effects") {
    queueEnabled = parseToggle(value);
  }

  else if (name === "effects_enabled") {
    setEffectsEnabled(parseToggle(value));
  }

  else if (name === "disabled_action_name") {
    disabledActionName = String(value || "").trim();
  }

  else if (name === "disabled_message_cooldown_seconds") {
    disabledMessageCooldownSeconds = readNumber(value, 15);
  }

  else if (name === "show_debug_panel") {
    showDebug = parseToggle(value);
    applyLiveLayout();
  }

  else if (name === "show_redemption_text") {
    showRedemptionText = parseToggle(value);
    if (!showRedemptionText) hideRedemptionBanner();
  }

  else if (name === "redemption_text_gap_px") {
    redemptionTextGapPx = readNumber(value, 22);
  }

  else if (name === "redemption_bottom_offset_px") {
    redemptionBottomOffsetPx = readNumber(value, 58);
    applyLiveLayout();
  }

  else if (name === "stop_current_effect") {
    effectQueue = [];
    finishCurrentEffect();
  }

  else if (name === "test_twerking_tina") {
    playEffect("twerking_tina", { effectUserName: "Test User", effectRewardName: "Twerking Tina" });
  }

  else if (name === "test_vibey_sponge") {
    playEffect("vibey_sponge", { effectUserName: "Test User", effectRewardName: "Vibey Sponge" });
  }

  else if (name === "test_crowd_cheer") {
    playEffect("crowd_cheer", { effectUserName: "Test User", effectRewardName: "Crowd Cheer" });
  }
}

applyLiveLayout();
